const items = $input.all();
const originals = $('Filtre doublons1').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const orig = originals[i]?.json || {};
  if (orig._empty) continue;
  try {
    let text = items[i].json.output || items[i].json.text || '';
    text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    text = text.replace(/,\s*}/g, '}').replace(/,\s*]/g, ']');

    const analysis = JSON.parse(text);

    // Convert pubDate to ISO 8601 or fallback to today
    let dateStr = null;
    if (orig.pubDate) {
      try {
        const d = new Date(orig.pubDate);
        if (!isNaN(d.getTime())) dateStr = d.toISOString().split('T')[0];
      } catch { }
    }
    if (!dateStr) dateStr = new Date().toISOString().split('T')[0];

    // Tags: ensure array
    let tags = analysis.tags || [];
    if (typeof tags === 'string') tags = tags.split(',').map(t => t.trim()).filter(Boolean);
    if (!Array.isArray(tags)) tags = [];

    results.push({
      json: {
        title: orig.title || analysis.titre || 'Sans titre',
        link: orig.link || '',
        source: orig.source || '',
        pubDate: dateStr,
        description: orig.description || '',
        resume: analysis.resume || analysis.r\u00e9sum\u00e9 || '',
        tags: tags,
        priorite: analysis.priorite || analysis.priorit\u00e9 || 'Moyenne'
      }
    });
  } catch (e) {
    let dateStr = null;
    if (orig.pubDate) {
      try {
        const d = new Date(orig.pubDate);
        if (!isNaN(d.getTime())) dateStr = d.toISOString().split('T')[0];
      } catch { }
    }
    if (!dateStr) dateStr = new Date().toISOString().split('T')[0];
    results.push({
      json: {
        title: orig.title || 'Sans titre',
        link: orig.link || '',
        source: orig.source || '',
        pubDate: dateStr,
        description: orig.description || '',
        resume: (orig.description || '').substring(0, 200),
        tags: [],
        priorite: 'Moyenne'
      }
    });
  }
}

return results.length > 0 ? results : [{json: {_skip: true}}];

