var items = $input.all();
var originals = $('Filtre Haute1').all();
var results = [];

for (var i = 0; i < items.length; i++) {
  var orig = originals[i] ? originals[i].json : {};
  var pageId = orig.pageId || '';
  var link = orig.link || '';

  // Browserless /content -> HTML dans $json.data
  var html = '';
  var d = items[i].json;
  if (typeof d === 'string') html = d;
  else if (typeof d.data === 'string') html = d.data;
  else if (typeof d.body === 'string') html = d.body;
  else html = JSON.stringify(d);

  // Nettoyage HTML
  html = html.replace(/<script[\s\S]*?<\/script>/gi, '');
  html = html.replace(/<style[\s\S]*?<\/style>/gi, '');
  html = html.replace(/<noscript[\s\S]*?<\/noscript>/gi, '');
  html = html.replace(/<nav[\s\S]*?<\/nav>/gi, '');
  html = html.replace(/<footer[\s\S]*?<\/footer>/gi, '');
  html = html.replace(/<header[\s\S]*?<\/header>/gi, '');
  html = html.replace(/<aside[\s\S]*?<\/aside>/gi, '');
  html = html.replace(/<form[\s\S]*?<\/form>/gi, '');

  var text = html.replace(/<[^>]+>/g, ' ');
  text = text.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  text = text.replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
  text = text.replace(/&#[0-9]+;/g, ' ').replace(/&[a-z]+;/gi, ' ');
  text = text.replace(/\s+/g, ' ').trim();

  // Limite totale : ~15 000 chars (~8 blocs) pour ne pas surcharger Notion
  var MAX_TOTAL = 15000;
  var CHUNK = 1900;  // limite Notion par bloc de texte
  text = text.substring(0, MAX_TOTAL);

  // Découpe le texte en chunks de 1900 chars
  var chunks = [];
  for (var j = 0; j < text.length; j += CHUNK) {
    var chunk = text.substring(j, j + CHUNK).trim();
    if (chunk) chunks.push(chunk);
  }
  if (chunks.length === 0) chunks = ['Contenu non disponible'];

  // Construit les blocs Notion
  var children = [
    {
      object: 'block', type: 'heading_2',
      heading_2: { rich_text: [{ type: 'text', text: { content: "Contenu de l'article" } }] }
    }
  ];

  // Un bloc paragraphe par chunk
  for (var k = 0; k < chunks.length; k++) {
    children.push({
      object: 'block', type: 'paragraph',
      paragraph: { rich_text: [{ type: 'text', text: { content: chunks[k] } }] }
    });
  }

  // Bookmark vers l'article original
  children.push({ object: 'block', type: 'bookmark', bookmark: { url: link } });

  var notionBody = JSON.stringify({ children: children });

  results.push({
    json: {
      pageId: pageId,
      link: link,
      blocks: chunks.length,
      notionBody: notionBody
    }
  });
}
return results;

